# find last assistant messages / tool outputs to see prior conclusions
def walk(o, depth=0):
    if isinstance(o, dict):
        if o.get('type') == 'message' and o.get('role') == 'assistant':
            txt = o.get('text','')
            if txt and ('PASS' in txt or 'persist' in txt.lower() or 'EFFECTIVE' in txt):
                print('---', txt[:1500].replace('\\n','\n'))
        for v in o.values():
            walk(v, depth+1)
    elif isinstance(o, list):
        for v in o:
            walk(v, depth+1)
